      "replace": "def _extract_text_content(content: Any) -> str:
    """Extract text content from message content, ignoring images.

    Handles both plain string items in a list and objects with a ``type`` attribute.
    """
    if content is None:
        return ''
    if isinstance(content, str):
        return content

    text_parts: list[str] = []
    for part in content:
        # Plain string items inside a list should be included verbatim
        if isinstance(part, str):
            text_parts.append(part)
        elif hasattr(part, 'type'):
            if part.type == 'text':
                text_parts.append(part.text)
            elif part.type == 'refusal':
                text_parts.append(f'[Refusal] {part.refusal}')
        # Skip image parts as they're handled separately

    return '\n'.join(text_parts)"
