  "test": "import pytest
from browser_use.llm.ollama.serializer import OllamaMessageSerializer
from browser_use.llm.messages import UserMessage

class MockPart:
    def __init__(self, type_: str, text: str = '', refusal: str = ''):
        self.type = type_
        self.text = text
        self.refusal = refusal

def test_extract_text_includes_plain_strings():
    # Content contains a plain string and a text-part object
    content = ["Hello ", MockPart(type_='text', text='world')]
    msg = UserMessage(content=content)
    serialized = OllamaMessageSerializer.serialize(msg)
    # Expected concatenation with newline separator
    assert serialized.content == "Hello \nworld"
